(function(){var STORAGE_KEY='ytai_consent_v1';function loadAds(){if(window.adsLoaded)return;window.adsLoaded=true;var script=document.createElement('script');script.async=true;script.src='';script.crossOrigin='anonymous';document.head.appendChild(script);}function loadGA(){if(window.gaLoaded)return;window.gaLoaded=true;var script=document.createElement('script');script.async=true;script.src='https://www.googletagmanager.com/gtag/js?id=G-2ZLELJGZEJ';document.head.appendChild(script);window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}window.gtag=gtag;gtag('js',new Date());gtag('config','G-2ZLELJGZEJ');}function showBanner(){var banner=document.createElement('div');banner.id='ytai-consent-banner';banner.style.cssText='position:fixed; bottom:0; left:0; right:0; background-color:#151515; color:#e0e0e0; padding:16px 24px; z-index:99999; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:16px; font-family:system-ui,-apple-system,sans-serif; font-size:14px; border-top:1px solid #333; box-shadow:0 -4px 15px rgba(0,0,0,0.5);';banner.innerHTML='<div style="flex:1; min-width:280px;"><strong style="color:#fff;">We value your privacy.</strong><br>We use cookies to enhance your experience, analyze site traffic, and serve personalized ads. <a href="/yt-ai/privacy" style="color:#4da6ff; text-decoration:underline;">Read our Privacy Policy</a>.</div><div style="display:flex; gap:12px;"><button id="ytai-reject" style="background:transparent; color:#ccc; border:1px solid #555; padding:8px 16px; border-radius:6px; cursor:pointer; font-weight:600;">Reject</button><button id="ytai-accept" style="background:#0077ff; color:#fff; border:none; padding:8px 16px; border-radius:6px; cursor:pointer; font-weight:600;">Accept All</button></div>';document.body.appendChild(banner);document.getElementById('ytai-accept').addEventListener('click',function(){localStorage.setItem(STORAGE_KEY,'accepted');banner.remove();loadAds();loadGA();});document.getElementById('ytai-reject').addEventListener('click',function(){localStorage.setItem(STORAGE_KEY,'rejected');banner.remove();});}var consent=localStorage.getItem(STORAGE_KEY);if(consent==='accepted'){loadAds();loadGA();}else if(consent===null){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',showBanner);}else{showBanner();}}})();
